 * Splits raw standard input into the three documents the merge operates on.
 */

/**
 * Splits `input` on newlines, dropping the empty tail a trailing newline
 * leaves, then groups the resulting lines into documents separated by lines
 * that read exactly `%%%`.
 *
 * @param {string} input Raw standard input.
 * @returns {string[][]} The documents found, in order.
 */
export function splitDocuments(input) {
  const lines = input.split('\n')
  if (input.endsWith('\n')) lines.pop()

  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') docs.push([])
    else docs[docs.length - 1].push(line)
  }
  return docs
}
"}

