{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-uiDP4E/src/diff.js","content":"/**
 * Computes the longest common subsequence of two documents and the changes
 * (runs of base lines replaced by runs of the other document's lines) that
 * fall outside it.
 */

/**
 * Finds the pairs of indices `[i, j]` such that `base[i] === other[j]` for
 * every pair, in order, that make up the longest common subsequence of
 * `base` and `other`. When several longest subsequences exist, the one
 * whose matches come earliest is chosen: walking both documents from the
 * start, a match is taken whenever the two current lines are equal, and
 * otherwise the side whose remaining subsequence is at least as long as the
 * other's is advanced, preferring to advance `base` when they tie.
 *
 * @param {string[]} base
 * @param {string[]} other
 * @returns {[number, number][]}
 */
export function lcsMatches(base, other) {
  const n = base.length
  const m = other.length

  // dp[i][j] holds the LCS length of base[i:] and other[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = base[i] === other[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === other[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Derives the changes between `base` and `other` from their LCS matches.
 * Each change is a run of base lines (from `baseStart` to `baseEnd`)
 * replaced by `lines`, the other document's lines that take their place. An
 * insertion has `baseStart === baseEnd`; a deletion has an empty `lines`.
 *
 * @param {string[]} base
 * @param {string[]} other
 * @returns {{baseStart: number, baseEnd: number, lines: string[]}[]}
 */
export function changesFrom(base, other) {
  const matches = lcsMatches(base, other)
  const changes = []
  let prevI = 0
  let prevJ = 0

  for (const [i, j] of matches) {
    if (i > prevI || j > prevJ) changes.push({ baseStart: prevI, baseEnd: i, lines: other.slice(prevJ, j) })
    prevI = i + 1
    prevJ = j + 1
  }
  if (prevI < base.length || prevJ < other.length) {
    changes.push({ baseStart: prevI, baseEnd: base.length, lines: other.slice(prevJ, other.length) })
  }
  return changes
}
"}

