{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-uiDP4E/src/regions.js","content":"/**
 * Groups the changes from both sides into merge regions and resolves each
 * one against the base.
 */

import { changesFrom } from './diff.js'

/**
 * @typedef {{baseStart: number, baseEnd: number, lines: string[]}} Change
 */

/**
 * @typedef {{type: 'stable', start: number, end: number}} StableRegion
 * @typedef {{
 *   type: 'mine' | 'theirs' | 'both',
 *   start: number,
 *   end: number,
 *   lines: string[],
 * }} ResolvedRegion
 * @typedef {{
 *   type: 'conflict',
 *   start: number,
 *   end: number,
 *   mine: string[],
 *   base: string[],
 *   theirs: string[],
 * }} ConflictRegion
 * @typedef {StableRegion | ResolvedRegion | ConflictRegion} Region
 */

/**
 * Reconstructs one side's lines for a span of the base by taking base lines
 * outside of that side's changes and that side's lines inside them.
 *
 * @param {string[]} base
 * @param {number} start
 * @param {number} end
 * @param {Change[]} changes Changes belonging to this side, in order.
 * @returns {string[]}
 */
function sideLines(base, start, end, changes) {
  const result = []
  let cursor = start
  for (const change of changes) {
    result.push(...base.slice(cursor, change.baseStart))
    result.push(...change.lines)
    cursor = change.baseEnd
  }
  result.push(...base.slice(cursor, end))
  return result
}

function sameLines(a, b) {
  return a.length === b.length && a.every((line, index) => line === b[index])
}

/**
 * Computes the merge regions for the three documents: stable stretches the
 * merge keeps unchanged, regions that resolve cleanly to one side or to a
 * change both sides made alike, and conflicts.
 *
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 * @returns {Region[]}
 */
export function buildRegions(mine, base, theirs) {
  const mineChanges = changesFrom(base, mine).map(change => ({ ...change, side: 'mine' }))
  const theirsChanges = changesFrom(base, theirs).map(change => ({ ...change, side: 'theirs' }))

  const all = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let cursor = 0
  let index = 0

  while (index < all.length) {
    let start = all[index].baseStart
    let end = all[index].baseEnd
    const group = [all[index]]
    index++
    while (index < all.length && all[index].baseStart <= end) {
      end = Math.max(end, all[index].baseEnd)
      group.push(all[index])
      index++
    }

    if (start > cursor) regions.push({ type: 'stable', start: cursor, end: start })
    regions.push(resolveRegion(base, start, end, group))
    cursor = end
  }
  if (cursor < base.length) regions.push({ type: 'stable', start: cursor, end: base.length })

  return regions
}

/**
 * @param {string[]} base
 * @param {number} start
 * @param {number} end
 * @param {(Change & {side: 'mine' | 'theirs'})[]} group
 * @returns {ResolvedRegion | ConflictRegion}
 */
function resolveRegion(base, start, end, group) {
  const mineChanges = group.filter(change => change.side === 'mine')
  const theirsChanges = group.filter(change => change.side === 'theirs')

  const mineLines = sideLines(base, start, end, mineChanges)
  const theirsLines = sideLines(base, start, end, theirsChanges)
  const baseLines = base.slice(start, end)

  if (sameLines(mineLines, theirsLines)) return { type: 'both', start, end, lines: mineLines }
  if (sameLines(mineLines, baseLines)) return { type: 'theirs', start, end, lines: theirsLines }
  if (sameLines(theirsLines, baseLines)) return { type: 'mine', start, end, lines: mineLines }
  return { type: 'conflict', start, end, mine: mineLines, base: baseLines, theirs: theirsLines }
}
"}

