 * Renders merge regions as the `merge`, `merge2` and `regions` output
 * formats.
 */

/**
 * @param {import('./regions.js').Region[]} regions
 * @param {{includeBase: boolean}} options
 * @returns {{lines: string[], hasConflict: boolean}}
 */
export function formatMerge(regions, { includeBase }) {
  const lines = []
  let hasConflict = false

  for (const region of regions) {
    if (region.type === 'stable') {
      // Stable regions carry no lines of their own; look them up from the
      // caller's base slice via the region bounds recorded on it.
      lines.push(...region.baseLines)
    } else if (region.type === 'conflict') {
      hasConflict = true
      lines.push('<<<<<<< mine', ...region.mine)
      if (includeBase) lines.push('||||||| base', ...region.base)
      lines.push('=======', ...region.theirs, '>>>>>>> theirs')
    } else {
      lines.push(...region.lines)
    }
  }

  return { lines, hasConflict }
}

/**
 * @param {import('./regions.js').Region[]} regions
 * @returns {{lines: string[], hasConflict: boolean}}
 */
export function formatRegions(regions) {
  const lines = []
  let hasConflict = false

  for (const region of regions) {
    if (region.type === 'stable') {
      lines.push(`stable ${region.baseLines.length}`)
    } else if (region.type === 'conflict') {
      hasConflict = true
      lines.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
    } else {
      lines.push(`${region.type} ${region.lines.length}`)
    }
  }

  return { lines, hasConflict }
}
"}

