/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { splitDocuments } from './parse.js'
import { buildRegions } from './regions.js'
import { formatMerge, formatRegions } from './format.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) fail('usage: cli.js merge|merge2|regions')

  const input = readFileSync(0, 'utf8')
  const docs = splitDocuments(input)
  if (docs.length !== 3) fail('expected three parts separated by %%%')

  const [mine, base, theirs] = docs
  const regions = buildRegions(mine, base, theirs)

  const { lines, hasConflict } =
    mode === 'regions' ? formatRegions(regions) : formatMerge(regions, { includeBase: mode === 'merge' })

  process.stdout.write(lines.length ? `${lines.join('\n')}\n` : '')
  process.exit(hasConflict ? 1 : 0)
}

main()
"}

